using System.Drawing;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    // .NET 9: StatusStrip default rendering changed from System to Professional.
    // Explicitly set the renderer to preserve the classic system look.
    public static void InitializeStatusStrip(StatusStrip statusStrip)
    {
        statusStrip.RenderMode = ToolStripRenderMode.System;
    }

    // .NET 9: IWindowsFormsEditorService.DropDownControl now throws
    // ArgumentNullException if control is null. Always guard against null.
    public static void SafeDropDown(IWindowsFormsEditorService editorService, Control? control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

